<template>
 <section class="qex-page" :class="{'has-frame':state.selected,maximized:state.maximized}" :data-variant="appearance.variant" aria-labelledby="qex-title">
  <header class="qex-hero"><div class="qex-hero-copy"><span class="qex-eyebrow">QGAUSS / A LITTLE MORE POSSIBILITY</span><h1 id="qex-title">给好点子，<em>多一片天地。</em></h1><p>打开一块新画布，让喜欢的工具和创作搭档待在一起。</p><div class="qex-hero-links"><span><i></i>{{ state.items.length }} 个扩展，等待新想法</span><router-link v-if="auth.isAdmin" to="/extensions/manage">整理我的工具箱 <ClientIcon name="arrowUpRight"/></router-link></div></div><div class="qex-sculpture" aria-hidden="true"><i></i><i></i><i></i><b>✳</b><span>A LITTLE EXTRA</span></div></header>
  <p v-if="state.notice" class="qex-notice" role="status">{{ state.notice }}</p>
  <div v-if="state.loading" class="qex-loading" role="status"><QLoader :size="30"/><span>正在打开工具箱…</span></div>
  <div v-if="state.error" class="qex-error" role="alert"><span>{{ state.error }}</span><button type="button" @click="work.load">重新读取</button></div>
  <div class="qex-layout">
   <section class="qex-catalog" aria-label="扩展工具箱"><header><div><span class="qex-eyebrow">SMALL TOOLS, BIG IDEAS</span><h2>{{ state.selected?'换一块画布':'今天想从哪里开始？' }}</h2></div><button v-if="state.selected" type="button" class="qex-text" :disabled="busy" @click="work.close()">收起画布 <ClientIcon name="close"/></button></header>
    <div class="qex-cards"><button v-for="item in state.items" :key="item.id" type="button" class="qex-card" :class="{selected:state.selected?.id===item.id}" :data-tone="item.tone" :disabled="busy" @click="work.open(item)"><div class="qex-card-art" aria-hidden="true"><i></i><span><ClientIcon :name="item.icon"/></span><b>✦</b></div><div class="qex-card-copy"><span>{{ item.builtin?'QGAUSS ORIGINAL':'YOUR TOOLBOX' }}</span><h3>{{ item.title }}</h3><p>{{ item.description }}</p><div><small>{{ item.chatEnabled?'可请求创作搭档':'专注工具体验' }}</small><ClientIcon name="arrowUpRight"/></div></div></button></div>
    <div v-if="!state.loading&&!state.items.length&&!state.error" class="qex-empty"><span>✳</span><h3>这里，还可以长出新工具。</h3><p>管理员添加扩展后，就可以在这里打开。</p></div>
   </section>
   <section v-if="state.selected" class="qex-frame-panel" :class="{expanded:state.maximized}" aria-label="扩展画布"><header><div><span class="qex-frame-dot" :class="{ready:state.frameReady}"></span><div><strong>{{ state.selected.title }}</strong><small>{{ state.frameReady?'画布已连接':'正在打开画布' }}</small></div></div><nav aria-label="画布操作"><a v-if="state.target&&!state.target.builtin" :href="state.target.src" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer" aria-label="在新窗口打开扩展"><ClientIcon name="arrowUpRight"/></a><button type="button" aria-label="重新打开扩展" :disabled="busy" @click="work.reload"><ClientIcon name="refresh"/></button><button type="button" :aria-label="state.maximized?'收回画布':'展开画布'" @click="state.maximized=!state.maximized"><ClientIcon name="layout"/></button></nav></header>
    <div class="qex-frame-body"><iframe v-if="state.target" :key="state.frameKey" ref="frame" :data-epoch="state.frameKey" :src="state.target.src" :sandbox="state.target.sandbox" referrerpolicy="no-referrer" allow="camera 'none'; microphone 'none'; geolocation 'none'; payment 'none'; clipboard-read 'none'; clipboard-write 'none'" title="QGauss 扩展画布" @load="work.frameLoaded" @error="work.frameFailed"></iframe><div v-if="state.frameLoading" class="qex-frame-loading" role="status"><QLoader :size="35"/><strong>正在展开新画布…</strong></div><div v-if="!state.target" class="qex-frame-unavailable"><ClientIcon name="apps"/><p>{{ state.frameError }}</p></div></div>
    <footer><span>{{ state.selected.builtin?'你的便签，只保留在当前账号的此窗口中。':'扩展独立运行，对话请求会在工作台确认。' }}</span><b>{{ state.frameReady?'CONNECTED':'OPENING' }}</b></footer><p v-if="state.frameError" class="qex-frame-note" role="status">{{ state.frameError }}</p>
   </section>
   <aside class="qex-assistant" aria-label="扩展创作请求"><header><span class="qex-assistant-icon"><ClientIcon name="chat"/></span><div><span class="qex-eyebrow">A LITTLE HELP, RIGHT HERE</span><h2>创作搭档，在这里。</h2></div></header>
    <template v-if="state.offer"><div class="qex-review-title"><span>✳ 新的创作请求</span><b>{{ state.selected?.title }}</b></div><div class="qex-request-prompt">{{ state.offer.prompt }}</div><div v-if="state.offer.quoteLoading" class="qex-quote-loading"><QLoader :size="19"/>正在确认搭档与费用…</div><div v-else-if="state.offer.quote" class="qex-quote"><span>本次搭档 <b>{{ state.offer.quote.modelName }}</b></span><span>使用次数 <strong>{{ state.offer.quote.cost ? state.offer.quote.cost+' '+poolName(state.offer.quote.pool)+'次数':'本次不扣次数' }}</strong></span><small v-if="state.offer.quote.demoMode">当前为演示回复。</small></div><p v-if="state.offer.error" class="qex-inline-error" role="alert">{{ state.offer.error }}</p><p class="qex-review-note">确认后，只把上面这段内容交给搭档。回复会回到此扩展，也会保存在你的对话记录中。</p><button type="button" class="qex-primary" :disabled="busy||state.offer.quoteLoading||!state.offer.quote||!!state.offer.error" @click="work.approve">确认，开始创作 <ClientIcon name="arrowUpRight"/></button><button type="button" class="qex-secondary" @click="work.rejectOffer()">这次先不继续</button></template>
    <template v-else-if="state.operation"><div class="qex-operation-heading"><span v-if="busy" class="qex-operation-loader"><QLoader :size="21"/></span><span v-else>✳</span><div><b>{{ stageTitle }}</b><small>{{ state.receipt?.extensionTitle||state.selected?.title||'扩展创作' }}</small></div></div><p v-if="state.operationError" class="qex-inline-error" role="status">{{ state.operationError }}</p><div v-if="state.reply" class="qex-response">{{ state.reply }}</div><p v-else class="qex-awaiting">{{ state.stage==='preparing'?'正在保存本次请求，随后交给搭档。':busy?'回复正在路上，可以在这里等一会儿。':'本次请求的结果会保留在这里。' }}</p><div v-if="state.receipt?.billing" class="qex-quote"><span>已使用<strong>{{ state.receipt.billing.charged }} {{ poolName(state.receipt.billing.pool) }}次数</strong></span><span v-if="state.receipt.billing.returned">已退回<strong>{{ state.receipt.billing.returned }} 次</strong></span><span v-if="state.receipt.billing.reserved">当前预留<strong>{{ state.receipt.billing.reserved }} 次</strong></span></div><div class="qex-operation-actions"><template v-if="state.stage==='unknown'"><button type="button" class="qex-primary" @click="work.check()">核对原请求</button><button v-if="state.receipt?.status==='READY'||state.receipt?.messageId" type="button" class="qex-secondary" @click="work.retry">继续这次请求</button></template><button v-if="busy" type="button" class="qex-secondary" :disabled="state.canceling||state.stage==='checking'" @click="work.cancel">{{ state.canceling?'正在核对停止结果…':state.receipt?.messageId?'请求停止生成':'结束这次等待' }}</button><button v-if="state.reply" type="button" class="qex-secondary" @click="copyReply">复制回复</button><router-link v-if="historyTarget" :to="historyTarget" class="qex-history-link">回到这次对话 <ClientIcon name="arrowUpRight"/></router-link><button v-if="!busy" type="button" class="qex-text" @click="work.dismiss">收起本次结果</button></div><p class="qex-review-note">生成与停止结果、已使用和退回的次数，请以保存的对话回执为准。</p></template>
    <div v-else class="qex-assistant-empty"><div aria-hidden="true"><i></i><span>◡</span><b>✦</b></div><h3>小问题，<em>也值得好好展开。</em></h3><p>在扩展里发起请求，这里会先接住你的问题。确认模型和次数后，搭档再开始创作。</p><span><i></i> 等待你的下一个想法</span></div>
   </aside>
  </div>
 </section>
</template>
<script setup>
import {computed,ref} from 'vue';
import {useAuth} from '../stores/auth.js';
import {useAppearance} from '../stores/appearance.js';
import {useExtensionWorkbench} from '../composables/useExtensionWorkbench.js';
import ClientIcon from '../components/reference/ClientIcon.vue';
import QLoader from '../components/QLoader.vue';
import '../components/design/extension-workbench.css';
const frame=ref(null),auth=useAuth(),appearance=useAppearance(),work=useExtensionWorkbench(frame),{state,busy,historyTarget}=work;
const stageTitle=computed(()=>({preparing:'接住了，正在准备。',running:'好想法，正在展开。',checking:'正在核对原请求。',canceling:'正在确认停止结果。',unknown:'先把这次结果核对好。',complete:'新的可能，已经到了。',failed:'这次还没顺利完成。',canceled:'这次创作已经停止。',ended:'这次等待已经结束。'}[state.stage]||'创作搭档，在这里。'));
const poolName=pool=>({model3:'基础',model4:'高级',drawMj:'绘画',agent:'应用'}[pool]||'创作');
async function copyReply(){try{await navigator.clipboard.writeText(state.reply);state.notice='回复已复制。';}catch{state.notice='当前无法直接复制，可以选中文字后复制。';}}
</script>
